CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash TEXT NOT NULL, role VARCHAR(20) NOT NULL CHECK (role IN ('STUDENT','DRIVER','ADMIN')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS drivers (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, license_number VARCHAR(80) NOT NULL UNIQUE, phone VARCHAR(30), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS routes (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS stops (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, latitude NUMERIC(9,6) NOT NULL CHECK (latitude BETWEEN -90 AND 90), longitude NUMERIC(9,6) NOT NULL CHECK (longitude BETWEEN -180 AND 180));
CREATE TABLE IF NOT EXISTS route_stops (route_id BIGINT NOT NULL REFERENCES routes(id) ON DELETE CASCADE, stop_id BIGINT NOT NULL REFERENCES stops(id) ON DELETE CASCADE, stop_order INTEGER NOT NULL CHECK (stop_order > 0), PRIMARY KEY (route_id,stop_id), UNIQUE(route_id,stop_order));
CREATE TABLE IF NOT EXISTS buses (id BIGSERIAL PRIMARY KEY, bus_number VARCHAR(40) NOT NULL UNIQUE, registration_number VARCHAR(40) NOT NULL UNIQUE, capacity INTEGER NOT NULL CHECK (capacity > 0), route_id BIGINT REFERENCES routes(id) ON DELETE SET NULL, status VARCHAR(20) NOT NULL DEFAULT 'INACTIVE' CHECK (status IN ('ACTIVE','INACTIVE','MAINTENANCE')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bus_assignments (id BIGSERIAL PRIMARY KEY, bus_id BIGINT NOT NULL UNIQUE REFERENCES buses(id) ON DELETE CASCADE, driver_id BIGINT NOT NULL UNIQUE REFERENCES drivers(id) ON DELETE CASCADE, assigned_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS active_routes (id BIGSERIAL PRIMARY KEY, bus_id BIGINT NOT NULL UNIQUE REFERENCES buses(id) ON DELETE CASCADE, driver_id BIGINT NOT NULL REFERENCES drivers(id) ON DELETE CASCADE, route_id BIGINT NOT NULL REFERENCES routes(id), started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), ended_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS location_history (id BIGSERIAL PRIMARY KEY, bus_id BIGINT NOT NULL REFERENCES buses(id) ON DELETE CASCADE, latitude NUMERIC(9,6) NOT NULL CHECK (latitude BETWEEN -90 AND 90), longitude NUMERIC(9,6) NOT NULL CHECK (longitude BETWEEN -180 AND 180), speed_kph NUMERIC(6,2), recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_route_stops_order ON route_stops(route_id,stop_order);
CREATE INDEX IF NOT EXISTS idx_location_history_bus_recorded ON location_history(bus_id,recorded_at DESC);
